        ('conversation', 'story', 5, {'en': 'Cultural Misunderstanding', 'pl': 'Kulturowe nieporozumienie', 'it': 'Cultural Misunderstanding'}, ['Un diplomatico ospita delegati da tre continenti.', 'Un regalo di orologi è bene intenzionato.', 'Un ospite lo interpreta come sfortuna.', 'Gli interpreti chiariscono il simbolismo.', "L'host si scusa e offre artigianato locale.", 'Le risate tornano durante un pasto condiviso.', 'I protocolli sono aggiornati per visite future.'], ['Dyplomata gości delegatów z trzech kontynentów.', 'Prezent zegarów jest dobry w intencji.', 'Jeden gość widzi w tym pech.', 'Tłumacze wyjaśniają symbolikę.', 'Gospodarz przeprasza i daje lokalne rękodzieło.', 'Śmiech wraca przy wspólnym posiłku.', 'Protokoły są aktualizowane na przyszłość.'], ['A diplomat hosts delegates from three continents.', 'A gift of clocks is meant kindly.', 'One guest interprets it as bad luck.', 'Interpreters pause and clarify symbolism.', 'The host apologizes and offers local crafts instead.', 'Laughter returns during a shared meal.', 'Protocols are updated for future visits.'], [{'word': 'diplomat', 'gloss': {'pl': 'dyplomata', 'en': 'diplomat'}, 'pos': 'noun'}, {'word': 'interpreter', 'gloss': {'pl': 'tłumacz', 'en': 'interpreter'}, 'pos': 'noun'}, {'word': 'protocol', 'gloss': {'pl': 'protokół', 'en': 'protocol'}, 'pos': 'noun'}], {'id': 'q1', 'type': 'comprehension', 'prompt': {'en': 'What gift causes trouble?', 'pl': 'Jaki prezent sprawia problem?'}, 'acceptedAnswers': {'en': ['clocks'], 'pl': ['zegary']}, 'explanation': {'en': 'Clocks are misinterpreted.', 'pl': 'Zegary są źle zinterpretowane.'}}, {'id': 'q2', 'type': 'comprehension', 'prompt': {'en': 'What replaces the gift?', 'pl': 'Czym zastępują prezent?'}, 'acceptedAnswers': {'en': ['local crafts'], 'pl': ['lokalne rękodzieło']}, 'explanation': {'en': 'Local crafts are offered.', 'pl': 'Oferują lokalne rękodzieło.'}}),
        ('technology', 'story', 6, {'en': 'Editing a Documentary', 'pl': 'Montaż dokumentu', 'it': 'Editing a Documentary'}, ['Un montatore assembla riprese da tre paesi.', 'Alcune interviste sono in lingue che non conosce.', 'I traduttori forniscono sottotitoli con note culturali.', 'Taglia una scena che sembra sensazionale.', 'I registi discutono ma mantengono la sua versione.', 'Il film debutta in un piccolo festival.', 'Le domande del pubblico riguardano la dignità, non il dramma.'], ['Montażystka składa materiał z trzech krajów.', 'Część wywiadów jest w językach, których nie zna.', 'Tłumacze dodają napisy z notami kulturowymi.', 'Wycina scenę, która wydaje się sensacyjna.', 'Reżyserzy dyskutują, ale zostawiają jej wersję.', 'Film premier na małym festiwalu.', 'Pytania publiczności dotyczą godności, nie dramatu.'], ['An editor assembles footage from three countries.', 'Some interviews are in languages she does not speak.', 'Translators provide subtitles with cultural notes.', 'She cuts a scene that feels sensational.', 'Directors debate but keep her version.', 'The film premieres at a small festival.', 'Audience questions focus on dignity, not drama.'], [{'word': 'footage', 'gloss': {'pl': 'materiał filmowy', 'en': 'footage'}, 'pos': 'noun'}, {'word': 'subtitle', 'gloss': {'pl': 'napisy', 'en': 'subtitle'}, 'pos': 'noun'}, {'word': 'premiere', 'gloss': {'pl': 'premiera', 'en': 'premiere'}, 'pos': 'noun'}], {'id': 'q1', 'type': 'comprehension', 'prompt': {'en': 'How many countries in footage?', 'pl': 'Z ilu krajów materiał?'}, 'acceptedAnswers': {'en': ['three'], 'pl': ['trzech']}, 'explanation': {'en': 'Footage from three countries.', 'pl': 'Materiał z trzech krajów.'}}, {'id': 'q2', 'type': 'comprehension', 'prompt': {'en': 'What does the audience focus on?', 'pl': 'Na czym skupia się publiczność?'}, 'acceptedAnswers': {'en': ['dignity'], 'pl': ['godności']}, 'explanation': {'en': 'Questions focus on dignity.', 'pl': 'Pytania o godność.'}}),
